}

.solari-flip-top {
  z-index: 3;
  animation: solari-flip-top var(--solari-duration) ease-in both;
}

.solari-flip-bottom {
  z-index: 3;
  animation: solari-flip-bottom var(--solari-duration) ease-out both;
}

@keyframes solari-flip-top {
  from {
    transform: rotateX(0deg);
  }
  to {
    transform: rotateX(-90deg);
  }
}

@keyframes solari-flip-bottom {
  from {
    transform: rotateX(90deg);
  }
  to {
    transform: rotateX(0deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .solari-board {
    --solari-duration: 0ms;
  }

  .solari-flip-top,
  .solari-flip-bottom {
    animation: none;
  }
}
